Here's a modern MSTest data-driven test class for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- DataRow: inline values for simple cases ---

    [TestMethod]
    [DataRow(100.0, 2, 200.0)]
    [DataRow(9.99, 1, 9.99)]
    [DataRow(0.0, 5, 0.0)]
    [DataRow(49.99, 0, 0.0, DisplayName = "Zero quantity returns zero")]
    public void CalculateTotal_WithVariousInputs_ReturnsExpected(
        double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.0, 10, 90.0)]
    [DataRow(200.0, 50, 100.0)]
    [DataRow(80.0, 0, 80.0, DisplayName = "No discount")]
    [DataRow(100.0, 100, 0.0, DisplayName = "Full discount")]
    public void ApplyDiscount_WithVariousPercents_ReturnsExpected(
        double price, int discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData with ValueTuples: preferred for complex/decimal data ---

    [TestMethod]
    [DynamicData(nameof(TotalTestData))]
    public void CalculateTotal_DynamicCases_ReturnsExpected(
        decimal price, int quantity, decimal expected)
    {
        var result = _calculator.CalculateTotal(price, quantity);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int quantity, decimal expected)> TotalTestData =>
    [
        (25.50m, 4, 102.00m),
        (0.01m, 100, 1.00m),
        (999.99m, 1, 999.99m),
    ];

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_DynamicCases_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int percent, decimal expected)> DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (75m, 100, 0m),
    ];

    // --- Edge case: invalid inputs throw ---

    [TestMethod]
    [DataRow(-1.0, 10)]
    [DataRow(100.0, -5)]
    [DataRow(100.0, 101)]
    public void ApplyDiscount_InvalidInputs_Throws(double price, int discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, discountPercent));
    }
}
```

**Key points:**

- **`DataRow`** — great for simple inline values. Note: `decimal` literals aren't allowed in attributes, so use `double` and cast.
- **`DynamicData` with ValueTuples** (MSTest 3.7+) — preferred for decimal precision and complex data; gives type safety and named parameters.
- **`Assert.ThrowsExactly`** — replaces `[ExpectedException]` for precise exception testing.
- **Sealed class** — modern best practice for performance/clarity.
- **DisplayName** — use on non-obvious cases for readable test output.

Adjust the method signatures (`CalculateTotal(decimal, int)`, `ApplyDiscount(decimal, int)`) to match your actual `PriceCalculator` API.
